/**
 *  Allow-list of providers `ai_connect` may start an OAuth flow for. Anything else is rejected
 *  by serde before the command runs.
 */
export type AiProvider = "openai-codex" | "anthropic" | "openrouter" | "nous";

/**
 *  `account` and `local` are provider-specific detail objects passed through from
 *  `hermes usage --json` / `island/ai-local-usage.py` (SPEC §5.2: the only untyped part).
 *  `account.accounts` contains explicit anthropic and openai-codex usage objects.
 *  `local.dashboard` contains 91-day session-start cohorts, hourly cohorts, period
 *  shares and recency-fenced active sessions. These are cumulative session costs,
 *  not a per-call ledger; its `periodBasis` and `note` must remain visible in UI.
 */
export type AiUsage = {
	account: JsonValue,
	local: JsonValue,
	providers: ProviderInfo[],
	fetchedAt: string,
};

export type AnchorKind = "enter" | "leave" | "pin";

/**
 *  Phase 2–6 only: feeds the legacy shim's `onAnchor`. Listener-only in Phase 2; the emitter
 *  arrives with `panel.sock` in Phase 3 (typed helper: `bus::emit_anchor`).
 */
export type AnchorSignal = AnchorKind;

export type AppNote = {
	id: string,
	title: string,
	body: string,
	createdMs: number,
	updatedMs: number,
	pinned: boolean,
};

export type Appearance = "skin" | "neutral" | "ocean" | "dune" | "dusk" | "silk" | "aurora" | "ember" | "rose" | "glacier" | 
/**  Fixed snapshot of the Necron-green Hermes look (Nov 2). */
"green" | 
/**  Palette derived from `customAccent`/`customBackground`/`customText` (Nov 2). */
"custom" | 
/**  Accent and tint taken from the playing track's artwork (Nov 5); falls back to Skin. */
"album" | "catppuccin-mocha" | "catppuccin-macchiato" | "catppuccin-frappe" | "catppuccin-latte" | "dracula" | "nord" | "gruvbox-dark" | "gruvbox-light" | "tokyo-night" | "tokyo-storm" | "rose-pine" | "rose-pine-moon" | "rose-pine-dawn" | "one-dark" | "solarized-dark" | "solarized-light";

export type ApprovalAnswer = {
	promptId: string,
	choice: string,
};

/**  Latest-value topic: `rev` wraps, consumers keep the newest. */
export type ApprovalChanged = {
	rev: number,
	prompt: ApprovalPrompt | null,
	/**
	 *  The terminal title says Hermes waits, but no structured request is known
	 *  (a sudo/secret prompt, or a TUI that is not mirroring): read-only "open terminal".
	 */
	waitingUnknown: boolean,
};

export type ApprovalChoiceView = {
	/**  What `approval_answer` takes back: `once|session|always|deny`, or `1`..`9` for clarify. */
	id: string,
	label: string,
	style: ChoiceStyle,
};

export type ApprovalKind = 
/**  A dangerous command waiting for once / session / always / deny. */
"approval" | 
/**  A clarify question with a short list of choices. */
"clarify";

export type ApprovalPrompt = {
	/**  The island's id for this prompt; an answer must carry the id it saw. */
	id: string,
	kind: ApprovalKind,
	/**  The command (approval) or the question (clarify), control characters replaced. */
	text: string,
	/**  The text was cut at the display limit, so it cannot be reviewed here. */
	textTruncated: boolean,
	description: string,
	choices: ApprovalChoiceView[],
	/**  Buttons may be pressed right now. */
	answerable: boolean,
	/**  An answer was already sent from the island; waiting for Hermes to settle it. */
	answered: boolean,
	/**  Why the buttons are off (shown instead of them), when `answerable` is false. */
	note: string | null,
	/**  Further requests queued behind this one. */
	more: number,
};

